const items = $input.all();
const today = new Date();
const eligibleCustomers = [];

for (const item of items) {
  const deliveredDate = new Date(item.json.delivered_date);
  const daysSinceDelivery = Math.floor((today - deliveredDate) / (1000 * 60 * 60 * 24));

  // Send review request between 3-10 days after delivery
  if (daysSinceDelivery >= 3 && daysSinceDelivery <= 10) {
    eligibleCustomers.push({
      json: {
        ...item.json,
        days_since_delivery: daysSinceDelivery
      }
    });
  }
}

console.log(`Found ${eligibleCustomers.length} customers eligible for review request`);
return eligibleCustomers;
